Lq[Oq]=Pq
end
local Qq=Kq~=nil and Kq.family==Gq.family and(Kq.buff==nil or Iq.buff==nil or Kq.buff==Iq.buff)
Jq[Gq.pid]={family=Gq.family,name=Gq.name,nums=Lq,buff=Iq.buff or(Kq and Kq.buff),who=Iq.who or Gq.who,trigger=Gq.trigger,keyword=Gq.keyword,sure=(Qq and(tonumber(Kq.runs)or 0)>=1)and Mje[2357]or Mje[2417],runs=(Qq and(tonumber(Kq.runs)or 0)or 0)+1,at=os.time(),why=Iq.why}
P.pasBook[Cq]=Jq
table.insert(Bq,{id=Cq,g=Gq,e=Jq[Gq.pid]})
elseif Hq and type(Iq)==Mje[1995]then
table.insert(Bq,{id=Cq,g=Gq,miss=Iq.why})
else
table.insert(Bq,{id=Cq,g=Gq,miss=Mje[2418]..tostring(Iq)})
end
end
end
end
pb._model={}
return Bq
end
