if js and js.kind==Mje[2165]and not(type(Xr.shred)==Mje[1995])then
local ps=tonumber(Xr.amp)
local qs=Hr and((type(Hr.ampTypes)==Mje[1995]and Hr.ampTypes[js.dtype])or(tonumber(Hr.amp)or 0)>0)
if ps and ps>0 and not qs then
Lr.fx,Mr=(Lr.fx or 0)+ps*V.TYPED_AMP_SHARE*ns*Or,true
end
elseif js and(js.kind==Mje[2112]or js.kind==Mje[2173])then
if not(Hr and((tonumber(Hr.stun)or 0)>0 or(tonumber(Hr.slowTime)or 0)>0))then
Lr.stun=(js.kind==Mje[2173]and 0.5 or 1)*ls
