function kb.xpRate()
local vbb=N.session()
if not vbb then
return 0
end
local wbb=0
for xbb,ybb in ipairs(kb.core())do
local zbb=vbb.collection:get_unit_by_uuid(ybb)
if zbb then
local Abb,Bbb=kb.gainXp(zbb,500000)
if Bbb>0 then
wbb=math.max(wbb,Abb/Bbb)
end
end
end
local Cbb=wbb*(O.strengthValue or 300)
if(tonumber(N.cur(Mje[2061]))or 0)>(O.xpGoldFloor or 100000)then
Cbb=math.min(Cbb,(N.GOLD_VALUE or 0.02)/14)
end
