function kb.xpGuess(Dbb)
local Ebb=Dbb.level and N.Levels[Dbb.level]
if not Ebb then
return 0
end
local Fbb=math.min(9,tonumber(Ebb.story_world_rank)or tonumber(Dbb.rank)or 9)
local Gbb=tonumber(Ebb.story_level_rank)or 6
local Hbb=(Dbb.kind==Mje[2035]and 1.5 or 1)*(Fbb>5 and 2 or 1)
local Ibb=2.1564^(Fbb-1)*(40+10*Gbb)/Hbb
if Dbb.kind==Mje[2014]then
Ibb=3*30*2.1564^(Fbb-1)/Hbb
end
local Jbb=Fbb>=9 and 0.3 or(Fbb>=7 and 0.5 or 1)
return Ibb*Jbb*6
end
function kb.modeBonus(Kbb)
