end
local Mbb=P.modes and P.modes[Kbb.key]
local Nbb=tonumber(Mbb and Mbb.xp)or kb.xpGuess(Kbb)
local Obb=Nbb*Lbb
if Obb<1 then
return 0
end
return Obb,string.format(Mje[3022],U.fmt(Nbb),math.floor(Obb+0.5))
