function kb.feedPlan(Ybb)
local Zbb=V.trait(Ybb)
local _bb=Zbb==Mje[3024]and 1.5 or 1
local acb=math.max(0,kb.xpFor(Ybb.unit_id,kb.cap(Ybb))-(tonumber(Ybb.xp)or 0))
local bcb,ccb,dcb={},0,0
for ecb,fcb in ipairs(kb.foodHeld())do
local gcb=fcb.xp*_bb
local hcb=math.min(fcb.n,math.floor((acb-ccb)/math.max(1,gcb)))
if hcb>0 then
bcb[fcb.id]=hcb
ccb=ccb+hcb*gcb
dcb=dcb+hcb
end
end
return{feed=bcb,planned=ccb,n=dcb}
end
function kb.run(icb)
