local wcb=kb.level(ucb)
local xcb=wcb>qcb and string.format(Mje[3020],qcb,wcb)or string.format(Mje[3021],qcb)
cb.add(string.format(Mje[3027],ocb,icb.name),ocb,Mje[3028],string.format(Mje[3029],U.fmt(vcb),xcb))
