local Xeb={[Ueb.uuid]=true,[O.evolveUnit]=true}
for Yeb,Zeb in ipairs(V.equipped())do
Xeb[Zeb.uuid]=true
end
for _eb,afb in ipairs(P.savedTeam or{})do
Xeb[afb]=true
end
for bfb,cfb in ipairs(P.train and P.train.on and P.train.on.base or{})do
Xeb[cfb]=true
end
local dfb,efb={},0
for ffb,gfb in pairs(Veb.profile_data.collection.owned_units)do
local hfb=N.Units[gfb.unit_id]
local ifb=hfb and ab.FUSE_RANK[hfb.rarity]
if ifb and ifb<=Web and not Xeb[ffb]then
local jfb=Veb.collection:get_unit_by_uuid(ffb)or gfb
if not(gfb._locked or jfb._locked)and not(gfb._equipped_relic or jfb._equipped_relic)then
local kfb,lfb=pcall(N.USC.calculate_xp_gain_from_fuse,Ueb,{jfb},Veb)
lfb=kfb and tonumber(lfb)or 0
if lfb>0 then
table.insert(dfb,{uuid=ffb,id=gfb.unit_id,xp=lfb,rarity=hfb.rarity})
efb=efb+lfb
end
end
end
end
table.sort(dfb,function(mfb,nfb)
if mfb.xp~=nfb.xp then
return mfb.xp<nfb.xp
end
return mfb.uuid<nfb.uuid
end)
local ofb=math.max(0,kb.xpFor(Ueb.unit_id,kb.cap(Ueb))-(tonumber(Ueb.xp)or 0))
local pfb,qfb={},0
for rfb,sfb in ipairs(dfb)do
if qfb>=ofb then
break
