if not Qfb then
return
end
local Rfb=V.name(Qfb.unit_id)
local Sfb,Tfb,Ufb=ab.xpFodder(Qfb)
if Ufb<=0 then
ab.pickNote.autoFuseXp=nil
return
end
if#Sfb==0 then
ab.pickNote.autoFuseXp=Mje[3120]
return
end
if os.time()-(tonumber(O.fuseXpOnAt)or 0)<30 then
ab.pickNote.autoFuseXp=Mje[3121]
return
end
ab.pickNote.autoFuseXp=nil
if F.req.back.fuseXp and U.now()<F.req.back.fuseXp then
