end
ab.fuseBatch=ab.fuseBatch or 50
local Vfb,Wfb,Xfb=0,0,{}
while F.alive and Vfb<10 and not P.pauseAll do
if Vfb>0 then
local Yfb,Zfb,_fb=ab.xpFodder(Pfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Qfb)
Sfb,Ufb={},_fb
for agb,bgb in ipairs(Yfb)do
if not Xfb[bgb.uuid]then
table.insert(Sfb,bgb)
end
end
if Ufb<=0 or#Sfb==0 then
break
end
end
local cgb={}
for dgb=1,math.min(ab.fuseBatch,#Sfb)do
table.insert(cgb,Sfb[dgb].uuid)
end
local egb=tonumber((Pfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Qfb).xp)or 0
local fgb=U.now()
local ggb,hgb=F.request(Mje[3122],Mje[3123],O.fuseXpUnit,cgb)
if not ggb and(hgb==Mje[2069]or hgb==Mje[2068])then
if hgb==Mje[2068]or Wfb>=3 then
break
end
Wfb=Wfb+1
task.wait(3.5)
continue
end
while U.now()-fgb<5 and(tonumber((Pfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Qfb).xp)or 0)<=egb do
task.wait(0.1)
end
local igb=tonumber((Pfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Qfb).xp)or 0
if igb>egb then
Vfb=Vfb+1
for jgb,kgb in ipairs(cgb)do
Xfb[kgb]=true
end
cb.add(string.format(Mje[3124],#cgb,Rfb),#cgb,Mje[3125],string.format(Mje[3126],U.fmt(igb-egb)))
F.log(1,Mje[2499],string.format(Mje[3127],#cgb,Rfb,U.fmt(igb-egb),kb.level(Pfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Qfb)))
elseif#cgb>20 then
ab.fuseBatch=20
F.log(1,Mje[2499],string.format(Mje[3128],#cgb,tostring(F.gameSaid(fgb)or(ggb and hgb)or Mje[2529])))
else
local lgb=F.gameSaid(fgb)
ab.pickNote.autoFuseXp=Mje[3129]..tostring(lgb or(ggb and hgb)or Mje[2529])..Mje[3130]
F.log(1,Mje[2499],Mje[3131]..tostring(lgb or(ggb and hgb)or Mje[2529]))
F.backoff(Mje[3122],1800)
break
end
end
end
