function ib.perRun(Cib,Dib)
local Eib=P.train.real[Cib]
if Eib and Eib.n>0 then
return Eib.sum/Eib.n,true
end
local Fib=db.hiveTrain(Cib,Dib)
if Fib then
return Fib,true
end
local Gib,Hib=0,0
local Iib=W.isInf(Cib)
for Jib,Kib in pairs(P.train.real)do
