function eb.upgradeGain(wBb,xBb,yBb,zBb,ABb,BBb)
local CBb,DBb=xBb[yBb],xBb[yBb+1]
local EBb=(CBb.cd>0 and CBb.damage/CBb.cd or 0)
local FBb=(DBb.cd>0 and DBb.damage/DBb.cd or 0)*V.aoe(DBb.atk,DBb.range)/math.max(0.3,V.aoe(CBb.atk,CBb.range))
local GBb=EBb>0 and wBb*(FBb/EBb-1)or(BBb or 0)
local HBb=xBb[yBb+2]
if HBb and yBb+1<xBb.max and HBb.cd>0 and DBb.cd>0 and EBb>0 then
local IBb=wBb*((HBb.damage/HBb.cd)/EBb-1)
local JBb=zBb+HBb.cost*ABb
if IBb/JBb>GBb/zBb then
GBb=GBb+(IBb/JBb*zBb-GBb)*0.5
end
end
local KBb=(DBb.range or 0)>(CBb.range or 0)and(1+((DBb.range-CBb.range)/math.max(1,CBb.range)))or 1
return math.max(0,GBb)*KBb
end
function eb.dpsFor(LBb,MBb)
if MBb<=0 then
return 0
end
local NBb={}
for OBb,PBb in ipairs(LBb)do
if not PBb.farm and PBb.gain>0 then
table.insert(NBb,PBb)
end
end
table.sort(NBb,function(QBb,RBb)
return QBb.gain/QBb.cost>RBb.gain/RBb.cost
end)
local SBb,TBb=0,0
for UBb,VBb in ipairs(NBb)do
if MBb<=0 then
break
end
TBb=VBb.gain/VBb.cost
local WBb=math.min(1,MBb/VBb.cost)
SBb=SBb+VBb.gain*WBb
MBb=MBb-VBb.cost*WBb
end
return SBb+math.max(0,MBb)*TBb*0.7
end
function eb.shieldDps(XBb,YBb,ZBb,_Bb,aCb,bCb,cCb)
if(_Bb or 0)<=0 or(XBb or 0)<=0 or(aCb or 0)<=0 then
return XBb or 0
end
YBb,ZBb,bCb=math.max(0.3,YBb or 2),math.max(1,ZBb or 1),bCb or 1
local dCb=XBb*bCb*YBb/ZBb
return aCb*ZBb/((_Bb/math.max(1,cCb or 1)+math.max(1,aCb/dCb))*YBb)/bCb
end
function eb.shieldGain(eCb,fCb,gCb,hCb,iCb,jCb,kCb,lCb)
local mCb,nCb=V.attackInfo(fCb.atk,fCb.range),V.attackInfo(hCb.atk,hCb.range)
local oCb=eb.shieldDps(eCb,(tonumber(fCb.cd)or 2)*(kCb or 1),mCb.n,iCb,jCb,lCb,mCb.hits)
local pCb=eb.shieldDps(gCb,(tonumber(hCb.cd)or 2)*(kCb or 1),nCb.n,iCb,jCb,lCb,nCb.hits)
local qCb=math.max(0,((tonumber(hCb.range)or 0)-(tonumber(fCb.range)or 0))/math.max(1,tonumber(fCb.range)or 1))
return math.max(0,pCb-oCb)+oCb*qCb
end
function eb.shieldWork(rCb,sCb,tCb,uCb,vCb,wCb,xCb,yCb,zCb)
if(uCb or 0)<=0 then
return 0
end
local ACb=3*uCb*(vCb or 1)/math.max(1,wCb or 20)
if(tCb or 0)>=ACb then
return 0
end
return math.max(1,rCb or 1)*math.max(1,zCb or 1)/math.max(0.3,sCb or 2)*math.min(xCb or 0,yCb or 0)
