function eb.holdGain(BCb,CCb,DCb,ECb)
if not BCb or(CCb or 0)<=0 then
return 0
end
local FCb,GCb=tonumber(BCb.stun)or 0,tonumber(BCb.slowTime)or 0
if FCb<=0 and GCb<=0 then
return 0
end
local HCb,ICb=FCb>0 and FCb or GCb,FCb>0 and 1 or(tonumber(BCb.slowPct)or 0.3)
local JCb=ICb*HCb/(HCb+(tonumber(BCb.ccCd)or 8))
local KCb=JCb/math.max(0.1,1-JCb)
return CCb*KCb*U.clamp(DCb or 0.5,0,1)*math.min(1,(tonumber(BCb.n)or 1)/2)/(1+(ECb or 0))
