function eb.bleedShare(SCb,TCb,UCb,VCb)
if SCb<=0 or not TCb then
return 0
end
if VCb then
return TCb==0 and SCb or SCb/(TCb+1)
end
return UCb<TCb and SCb/(TCb-UCb)or 0
end
function eb.keepsUp(WCb,XCb,YCb,ZCb,_Cb)
local aDb=WCb.coming
if not(aDb and#aDb>0 and WCb.waveSec)then
return true
end
local bDb=WCb.eff or 1
local cDb=WCb.money-YCb
local dDb=(WCb.teamDps or 0)*(WCb.shieldK or 1)+(ZCb or 0)*bDb+eb.dpsFor(XCb,math.max(0,cDb))*bDb
local eDb=(WCb.farmNow or 0)+(_Cb or 0)
local fDb=(WCb.roadSec or 130)*U.clamp(WCb.cover or 0.6,0.1,1)
local gDb=WCb.hpAlive or 0
for hDb,iDb in ipairs(aDb)do
gDb=math.max(0,gDb+iDb.hp-dDb*WCb.waveSec)
local jDb=dDb*fDb
if gDb>jDb then
return false,hDb,jDb/math.max(1,gDb)
end
if hDb< #aDb then
dDb=dDb+eb.dpsFor(XCb,(iDb.reward or 0)+eDb)*bDb*(0.85^hDb)
end
end
