function jb.roomLearn(_nc)
if _nc or bb.kind~=Mje[2015]or bb.roomLearned then
return
end
local aoc=P.dg.room
local boc,coc=bb.pred,bb.calRun
if type(aoc)~=Mje[1995]or aoc.seed==nil or type(boc)~=Mje[1995]or not boc.won or type(coc)~=Mje[1995]then
return
end
local function doc(eoc,foc)
return type(eoc)==Mje[1995]and tonumber(eoc[foc]or eoc[tostring(foc)])or nil
end
local goc={}
for hoc=2,bb.wave()do
local ioc,joc=doc(coc.alive,hoc),doc(boc.aliveAt,hoc)
if ioc and joc and ioc>0 and joc>0 then
table.insert(goc,ioc/joc)
end
end
if#goc<3 then
return
end
table.sort(goc)
local koc=goc[math.ceil(#goc/2)]
bb.roomLearned=true
if koc<=1.05 then
