end
P.dg.roomK=type(P.dg.roomK)==Mje[1995]and P.dg.roomK or{}
local loc=tostring(aoc.seed)
local moc=P.dg.roomK[loc]
local noc=math.min(jb.ROOM_K_MAX,jb.roomK(loc)*koc)
P.dg.roomK[loc]={k=noc,n=(type(moc)==Mje[1995]and tonumber(moc.n)or 0)+1,at=os.time(),d=aoc.d}
bb.roomKUp=true
local ooc={}
