table.insert(ooc,{s=poc,at=type(qoc)==Mje[1995]and tonumber(qoc.at)or 0})
end
table.sort(ooc,function(roc,soc)
return roc.at>soc.at
end)
for toc=31,#ooc do
P.dg.roomK[ooc[toc].s]=nil
end
F.log(1,Mje[3915],string.format(Mje[4027],tostring(aoc.d),koc,noc))
end
