function bb.buildPath()
bb.samples={}
local Voc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not Voc then
return
end
for Woc,Xoc in pairs(Voc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[Woc.Name])then
local Yoc={}
for Zoc,_oc in ipairs(Xoc.points or{})do
table.insert(Yoc,_oc.part.Position)
end
local apc=0
for bpc=2,#Yoc do
apc=apc+(Yoc[bpc]-Yoc[bpc-1]).Magnitude
end
local cpc=0
for dpc=2,#Yoc do
local epc,fpc=Yoc[dpc-1],Yoc[dpc]
local gpc=(fpc-epc).Magnitude
local hpc=math.max(1,math.floor(gpc/2))
for ipc=0,hpc-1 do
local jpc=epc:Lerp(fpc,ipc/hpc)
table.insert(bb.samples,{pos=jpc,prog=(cpc+gpc*ipc/hpc)/math.max(1,apc),lane=Woc.Name})
end
cpc=cpc+gpc
end
if Yoc[#Yoc]then
table.insert(bb.samples,{pos=Yoc[#Yoc],prog=1,lane=Woc.Name})
end
end
end
pcall(bb.readHidden,Voc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local kpc=tonumber(bb.ld and bb.ld._portal_lanes)
local lpc=gb.laneList(bb.samples)
if kpc and kpc>=1 and lpc and#lpc>kpc then
bb.laneWant=kpc
end
bb.laneTotal=lpc and#lpc or 1
bb.countLanes()
end
function bb.readHidden(mpc)
local npc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(npc)~=Mje[1995]or not next(npc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local opc
for ppc,qpc in pairs(mpc)do
if npc[ppc.Name]and type(qpc.points)==Mje[1995]and#qpc.points>=2 then
local rpc={}
for spc,tpc in ipairs(qpc.points)do
rpc[spc]=U.flat(tpc.part.Position)
end
local upc={}
for vpc,wpc in ipairs(bb.samples)do
local xpc=tostring(wpc.lane)
upc[xpc]=upc[xpc]or{}
table.insert(upc[xpc],wpc)
end
local ypc,zpc
for Apc,Bpc in pairs(upc)do
local Cpc=0
for Dpc=1,#rpc,math.max(1,math.floor(#rpc/20))do
local Epc=math.huge
for Fpc,Gpc in ipairs(Bpc)do
local Hpc=(U.flat(Gpc.pos)-rpc[Dpc]).Magnitude
if Hpc<Epc then
Epc=Hpc
end
end
Cpc=Cpc+Epc
end
if not zpc or Cpc<zpc then
ypc,zpc=Apc,Cpc
end
end
local Ipc,Jpc,Kpc,Lpc,Mpc,Npc={},nil,nil,nil,0,0
for Opc,Ppc in ipairs(rpc)do
local Qpc,Rpc=nil,math.huge
for Spc,Tpc in ipairs(upc[ypc])do
local Upc=(U.flat(Tpc.pos)-Ppc).Magnitude
if Upc<Rpc then
Rpc,Qpc=Upc,Tpc.prog
end
end
Npc=math.max(Npc,Rpc)
if Kpc then
local Vpc=Qpc-Kpc
local Wpc=(Vpc>0.002 and 1)or(Vpc< -0.002 and-1)or Lpc
if Lpc and Wpc and Wpc~=Lpc then
table.insert(Ipc,math.floor(Kpc*1000+0.5)/1000)
end
Lpc,Mpc=Wpc or Lpc,Mpc+math.abs(Vpc)
else
Jpc=Qpc
end
Kpc=Qpc
if Opc%50==0 then
task.wait()
end
end
if Kpc and Npc<=8 then
table.insert(Ipc,math.floor(Kpc*1000+0.5)/1000)
opc=opc or{}
opc[ppc.Name]={from=math.floor((Jpc or 0)*1000+0.5)/1000,len=math.floor(Mpc*1000+0.5)/1000,turns=Ipc,road=ypc}
end
end
end
if not opc then
return
end
local Xpc=bb.ld.map
P.maps[Xpc]=P.maps[Xpc]or{}
local Ypc=P.maps[Xpc].hidden
P.maps[Xpc].hidden=opc
if type(Ypc)~=Mje[1995]then
for Zpc,_pc in pairs(opc)do
F.log(1,Mje[2663],string.format(Mje[4043],Zpc,_pc.len,tostring(_pc.road),math.floor((#_pc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local aqc,bqc,cqc={},0,0
for dqc,eqc in ipairs(bb.samples)do
local fqc=tostring(eqc.lane)
if not aqc[fqc]then
bqc=bqc+1
end
aqc[fqc]=(aqc[fqc]or 0)+1
cqc=cqc+1
end
bb.laneCount={n=bqc,by=aqc,avg=bqc>0 and cqc/bqc or 1}
if bqc>=2 then
local gqc,hqc=pcall(gb.laneSep,bb.samples)
local iqc=P.maps[bb.mapKey()]
if gqc and hqc and type(iqc)==Mje[1995]then
iqc.sep=hqc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local jqc,kqc={},0
for lqc,mqc in ipairs(workspace._UNITS:GetChildren())do
local nqc=mqc:FindFirstChild(Mje[2058])
if nqc and nqc:FindFirstChild(Mje[4044])and nqc.player.Value==nil and nqc:FindFirstChild(Mje[4045])and mqc:FindFirstChild(Mje[3243])then
local oqc=tostring(nqc.lane.Value)
if not jqc[oqc]then
jqc[oqc]=true
kqc=kqc+1
end
end
end
if kqc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,Mje[2663],Mje[4046])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if kqc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local pqc,qqc={},{}
for rqc,sqc in ipairs(bb.samples)do
if jqc[tostring(sqc.lane)]then
table.insert(pqc,sqc)
end
end
if#pqc==0 then
bb.laneWant=nil
return true
end
for tqc in pairs(jqc)do
table.insert(qqc,tqc)
end
table.sort(qqc)
bb.samples,bb.laneCut=pqc,table.concat(qqc,Mje[2309])
bb.countLanes()
local uqc,vqc=pcall(bb.buildCandidates)
if not uqc then
F.log(1,Mje[2381],Mje[4047]..tostring(vqc))
end
F.log(1,Mje[2663],string.format(Mje[4048],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local wqc,xqc=pcall(bb.planSpots)
bb.planning=nil
if not wqc then
F.log(1,Mje[2381],Mje[4049]..tostring(xqc))
end
end)
end
return true
end
function bb.buildWaves()
local yqc=bb.ld
local zqc=yqc and yqc._dungeon and type(yqc._override_waves)==Mje[1995]and yqc._override_waves or nil
local Aqc=yqc and N.Waves[(zqc and zqc.template)or yqc.waves or yqc.id]
local Bqc
if type(Aqc)==Mje[1995]then
Bqc=Aqc.override_waves or Aqc.waves
if not Bqc and Aqc.template and N.Waves[Aqc.template]then
Bqc=N.Waves[Aqc.template].waves or N.Waves[Aqc.template].override_waves
end
end
bb.waveList=U.list(Bqc)
bb.infinite=yqc and(yqc._gamemode==Mje[2014]or yqc.infinite)and gb.unbound(yqc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
return
end
bb.total=(yqc and type(yqc._dungeon)==Mje[1995]and 15)or tonumber(yqc and yqc._override_infinite_bound_waves)or gb.boundEnd(yqc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
function bb.infExtend()
