function bb.infWave(Cqc)
bb.infWaveAt=bb.infWaveAt or{}
bb.infWaveAt[Cqc]=bb.infWaveAt[Cqc]or U.now()
bb.infExtend()
if O.trainLeave and not bb.stopping then
local Dqc,Eqc=pcall(bb.trainLeave,Cqc)
if not Dqc then
F.log(1,Mje[2381],Mje[4050]..tostring(Eqc))
end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=Mje[3537]and bb.kind~=Mje[2450]then
local Fqc,Gqc=pcall(bb.infStop,Cqc)
if not Fqc then
F.log(1,Mje[2381],Mje[4051]..tostring(Gqc))
end
end
local Hqc=W.infTier(Cqc-1)
if Hqc<=0 or Hqc==bb.infTierSeen then
return
end
bb.infTierSeen=Hqc
task.delay(5,function()
if not F.alive then
return
end
local Iqc=N.prof()
local Jqc=Iqc and Iqc.daily_infinite_reward_claims and Iqc.daily_infinite_reward_claims[bb.ld.id]
local Kqc=type(Jqc)==Mje[1995]and(tonumber(Jqc.highest_claimed_wave)or 0)>=Hqc and os.time()-(tonumber(Jqc.highest_claim_time)or 0)<900
if Kqc then
P.infLive=true
end
F.log(1,Mje[2663],string.format(Mje[4052],Hqc,Kqc and Mje[4053]or Mje[4054]))
end)
end
function bb.infStop(Lqc)
local Mqc=0
for Nqc,Oqc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
Mqc=math.max(Mqc,tonumber(Oqc.wave)or 0)
end
if Mqc<=0 or Lqc<=Mqc+1 then
return
end
local Pqc=P.train.on
if bb.trainee and Pqc and Pqc.have+(Pqc.got or 0)+(bb.trainTk or 0)<Pqc.need then
return
end
if not ab.every(Mje[4055],60)then
return
end
local Qqc=W.rec(bb.key)
local Rqc=tonumber(Qqc.timed)or 0
local Sqc=W.INF_PAY
local Tqc
if Lqc>=(Sqc.cap+Sqc.less)/Sqc.per then
Tqc=0
else
local Uqc=bb.infWaveAt or{}
local Vqc,Wqc=Uqc[Lqc],Uqc[Lqc-5]
if Vqc and Wqc and Vqc>Wqc then
Tqc=Sqc.per*5/((Vqc-Wqc)/60)
end
if not Tqc then
Tqc=(Rqc>0 and(Qqc.sec or 0)>0)and math.max(0.5,(Qqc.gems or 0)/(Qqc.sec/60))or 2.5
end
end
local Xqc=pcall(W.pick)
local Yqc
for Zqc,_qc in ipairs(Xqc and W.lastScored or{})do
if _qc.kind~=Mje[2014]and(not Yqc or(_qc.score or 0)>(Yqc.score or 0))then
Yqc=_qc
end
end
if not Yqc or(Yqc.score or 0)<=Tqc then
return
end
bb.stopping=true
F.log(1,Mje[2663],string.format(Mje[4056],Lqc,Tqc,Yqc.score,Yqc.label))
bb.sellAll()
end
function bb.trainLeave(arc)
local brc=P.train.on
if not(bb.infinite and bb.trainee and brc)then
return
end
bb.trainCount()
local crc=brc.have+(brc.got or 0)+(bb.trainTk or 0)
if crc<brc.need then
return
end
local drc,erc,frc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if drc and(erc or 0)>0 and frc>0 and arc<=frc then
F.status(Mje[3207],string.format(Mje[4057],V.name(brc.id),brc.what,frc))
return
end
bb.stopping=true
F.log(1,Mje[2663],string.format(Mje[4058],V.name(brc.id),brc.what,U.fmt(crc),U.fmt(brc.need),arc))
bb.sellAll()
end
function bb.sellAll()
task.spawn(function()
local grc={}
for hrc,irc in ipairs(bb.mine or{})do
local jrc=irc:FindFirstChild(Mje[2058])
local krc=jrc and jrc:FindFirstChild(Mje[2372])and N.Units[jrc.id.Value]
if not(krc and krc.unsellable)then
table.insert(grc,irc)
