return nrc and nrc:FindFirstChild(Mje[2372])and V.isFarm(nrc.id.Value)or false
end
table.sort(grc,function(orc,prc)
return(lrc(orc)and 1 or 0)<(lrc(prc)and 1 or 0)
end)
local qrc={}
for rrc=1,2 do
local trc={}
for urc,vrc in ipairs(rrc==1 and grc or qrc)do
