end
end
qrc=trc
end
if#qrc>0 then
local yrc={}
for zrc,Arc in ipairs(qrc)do
table.insert(yrc,Arc.Name)
end
F.log(1,Mje[2663],Mje[4060]..table.concat(yrc,Mje[2107])..Mje[4061])
end
end)
