qMc.sec,qMc.wave=type(qMc.sec)==Mje[1995]and qMc.sec or{},type(qMc.wave)==Mje[1995]and qMc.wave or{}
if rMc and tonumber(sMc)then
table.insert(qMc.sec,math.floor(sMc+0.5))
end
table.insert(qMc.wave,tonumber(tMc)or 0)
if tonumber(uMc)then
qMc.kills=type(qMc.kills)==Mje[1995]and qMc.kills or{}
table.insert(qMc.kills,math.floor(tonumber(uMc)))
while#qMc.kills>bb.LAYOUT_KEEP do
table.remove(qMc.kills,1)
end
end
while#qMc.sec>bb.LAYOUT_KEEP do
table.remove(qMc.sec,1)
end
while#qMc.wave>bb.LAYOUT_KEEP do
table.remove(qMc.wave,1)
end
end
function bb.layoutJudge(vMc,wMc,xMc,yMc)
local zMc,AMc=tonumber(vMc and vMc.runs)or 0,tonumber(wMc and wMc.runs)or 0
if zMc<1 or AMc<bb.LAYOUT_CONTROL then
