end
if yMc and type(vMc.kills)==Mje[1995]and type(wMc.kills)==Mje[1995]and#vMc.kills>=1 and#wMc.kills>=bb.LAYOUT_CONTROL then
local BMc,CMc=bb.labMedian(vMc.kills),bb.labMedian(wMc.kills)
if BMc and CMc and BMc<CMc*0.97 and(#vMc.kills>=2 or BMc<CMc*0.85)then
return string.format(Mje[4225],BMc,CMc)
end
return nil
end
local DMc,EMc=(tonumber(vMc.wins)or 0)/zMc,(tonumber(wMc.wins)or 0)/AMc
if not xMc and EMc>=0.5 then
if DMc+0.25<EMc and(zMc>=2 or(DMc==0 and EMc>=0.9 and AMc>=3))then
return string.format(Mje[4226],tonumber(vMc.wins)or 0,zMc,zMc==1 and Mje[916]or Mje[1843],tonumber(wMc.wins)or 0,AMc)
end
local FMc,GMc=bb.labMedian(vMc.sec),bb.labMedian(wMc.sec)
if FMc and GMc and FMc>GMc*1.10 and(#vMc.sec>=2 or FMc>GMc*1.25)then
return string.format(Mje[4227],math.floor(FMc/60),FMc%60,math.floor(GMc/60),GMc%60)
