bb.CONTROL_WORDS={Mje[4231],Mje[4232],Mje[4233],Mje[4234]}
function bb.controlSpot(WMc,XMc)
if not bb.killZone()then
return nil
end
local YMc=gb.holds
if not YMc(WMc.id)or V.toggleOf(WMc.id)then
return nil
end
local ZMc,_Mc,aNc,bNc=1,0,0,{}
local cNc=bb.hurtSamples()
for dNc,eNc in ipairs(bb.mine or{})do
local fNc=eNc._stats
local gNc=fNc.id.Value
if fNc:FindFirstChild(Mje[2247])and not V.isFarm(gNc)and not V.allyBuff(gNc)then
local hNc,iNc=U.flat(eNc:GetPivot().Position),fNc.range.Value
if YMc(gNc)and not V.toggleOf(gNc)then
aNc=aNc+1
table.insert(bNc,{p=hNc,r=iNc})
else
for jNc,kNc in ipairs(cNc)do
if(U.flat(kNc.pos)-hNc).Magnitude<=iNc then
ZMc,_Mc=math.min(ZMc,kNc.prog),math.max(_Mc,kNc.prog)
end
end
end
end
end
if _Mc<=ZMc then
ZMc,_Mc=0.75,0.98
end
local lNc=(XMc or aNc)+1
local mNc=({ZMc,_Mc,(ZMc+_Mc)/2,ZMc-(_Mc-ZMc)/2})[lNc]
if not mNc then
return nil
end
local nNc=V.range(WMc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local oNc={}
for pNc,qNc in ipairs(bb.cands)do
local rNc,sNc,tNc=U.flat(qNc),0,0
for uNc,vNc in ipairs(cNc)do
if(U.flat(vNc.pos)-rNc).Magnitude<=nNc then
tNc=tNc+1
if math.abs(vNc.prog-mNc)<=0.05 then
sNc=sNc+1
local wNc=U.flat(vNc.pos)
for xNc,yNc in ipairs(bNc)do
if(wNc-yNc.p).Magnitude<=yNc.r then
sNc=sNc-0.5
break
end
end
end
end
end
if sNc>0 then
table.insert(oNc,{pos=qNc,sc=sNc,cov=tNc})
end
if pNc%60==0 then
task.wait()
end
end
table.sort(oNc,function(zNc,ANc)
return zNc.sc>ANc.sc
end)
for BNc,CNc in ipairs(oNc)do
local DNc=bb.valid(CNc.pos,WMc.data)
if DNc then
F.log(1,Mje[4083],string.format(Mje[4235],V.name(WMc.id),bb.CONTROL_WORDS[lNc],math.floor(mNc*100+0.5)))
return DNc,CNc.cov,mNc
end
if BNc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(ENc)
local FNc,GNc=gb.holds(ENc.id)
if not FNc then
return nil
end
if V.killFed(ENc.id)then
return nil
end
local HNc,INc={},0
for JNc,KNc in ipairs(bb.mine or{})do
local LNc=KNc._stats
local MNc=LNc.id.Value
if LNc:FindFirstChild(Mje[2247])and not V.isFarm(MNc)and not V.allyBuff(MNc)and MNc~=ENc.id then
local NNc,ONc=pcall(bb.liveDps,KNc,MNc)
ONc=NNc and tonumber(ONc)or 0
if ONc>0 then
table.insert(HNc,{p=U.flat(KNc:GetPivot().Position),r=LNc.range.Value,d=ONc})
INc=INc+ONc
end
end
end
if#HNc==0 or INc<=0 then
return nil
end
local PNc=bb.hurtSamples()
local QNc={}
for RNc,SNc in ipairs(PNc)do
local TNc,UNc=U.flat(SNc.pos),0
for VNc,WNc in ipairs(HNc)do
if(TNc-WNc.p).Magnitude<=WNc.r then
UNc=UNc+WNc.d
end
end
QNc[RNc]=UNc/INc
end
local XNc=V.range(ENc.u,math.min(tonumber(GNc)or 0,3,V.rows(ENc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local YNc,ZNc,_Nc
for aOc,bOc in ipairs(bb.cands)do
local cOc,dOc,eOc=U.flat(bOc),0,0
for fOc,gOc in ipairs(PNc)do
if(U.flat(gOc.pos)-cOc).Magnitude<=XNc then
dOc=dOc+QNc[fOc]
eOc=eOc+1
end
end
if dOc>0 and(not ZNc or dOc>ZNc)then
local hOc=bb.valid(bOc,ENc.data)
if hOc then
YNc,ZNc,_Nc=hOc,dOc,eOc
end
end
if aOc%40==0 then
task.wait()
end
end
if not YNc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[ENc.id]then
bb.holdSaid[ENc.id]=true
F.log(1,Mje[4083],string.format(Mje[4236],V.name(ENc.id)))
end
return YNc,_Nc or 0
end
function bb.bestSpot(iOc,jOc,kOc)
