if(UVc.stun or 0)<=0 and(UVc.slowTime or 0)<=0 then
return 0
end
local VVc=0
for WVc,XVc in ipairs(bb.mine or{})do
local YVc=XVc._stats
local ZVc=V.rows(YVc.id.Value)
local _Vc=ZVc and ZVc[math.min(YVc.upgrade.Value,ZVc.max)]
local aWc=_Vc and _Vc.atk and V.attackInfo(_Vc.atk,_Vc.range)
if aWc and((aWc.stun or 0)>0 or(aWc.slowTime or 0)>0)then
VVc=VVc+1
end
end
local bWc,cWc=gb.mask(bb.info.map,V.range(SVc.u,0)*(bb.info.rangeScale or 1)),0
for dWc=1,gb.BINS do
if bWc[dWc]then
cWc=cWc+1
end
end
