local fWc=(V.airFrom(SVc.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(UVc,bb.teamDps or 0,cWc/(math.max(0.1,eWc)*gb.BINS)*fWc,VVc)
