function bb.buffGain(gWc)
local hWc=V.allyBuff(gWc.id)
if not hWc then
return 0
end
local iWc,jWc,kWc=bb.buffShort(hWc)
local lWc=V.stackCap(hWc.attack)
local mWc,nWc=pcall(V.range,gWc.u,0)
nWc=(mWc and tonumber(nWc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local oWc=lWc and O.community and tonumber(hWc.time)and tonumber(kWc)
local function pWc(qWc,rWc)
local sWc=math.floor(qWc*hWc.time/math.max(1,kWc)+0.001)
return math.min(lWc,(1+rWc)^sWc-1)
end
local tWc=0
for uWc,vWc in ipairs(iWc)do
local wWc=0
for xWc,yWc in ipairs(iWc)do
if(yWc.pos-vWc.pos).Magnitude<=nWc then
local zWc=hWc.types[yWc.base]
local AWc=zWc*hWc.uptime
if oWc then
local BWc,CWc=pWc(yWc.n,zWc),yWc.n+1
while CWc<yWc.n+6 and pWc(CWc,zWc)<=BWc+0.001 do
CWc=CWc+1
end
AWc=math.max(0,(pWc(CWc,zWc)-BWc)/(CWc-yWc.n))
elseif lWc then
AWc=math.max(0,math.min(lWc,(yWc.n+1)*zWc*hWc.uptime)-math.min(lWc,yWc.n*zWc*hWc.uptime))
