bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(Nbd,Obd)
local Pbd=(Obd.t or 0)-(Nbd.t or 0)
if Pbd<bb.BASE_WIN-1 then
return false
end
local Qbd=((tonumber(Nbd.base)or 0)-(tonumber(Obd.base)or 0))/Pbd
if Qbd<=0 or(tonumber(Obd.base)or 0)<=0 then
return false
end
local Rbd=Obd.base/Qbd
local Sbd,Tbd=0,0
local Ubd,Vbd=Nbd.foes or{},Obd.foes or{}
for Wbd,Xbd in pairs(Vbd)do
if Xbd.prog>=bb.BASE_END then
Sbd=Sbd+Xbd.hp
local Ybd=Ubd[Wbd]
if Ybd then
Tbd=Tbd+math.max(0,Ybd.hp-Xbd.hp)
end
end
end
for Zbd,_bd in pairs(Ubd)do
if _bd.prog>=bb.BASE_END and not Vbd[Zbd]then
Tbd=Tbd+_bd.hp
end
end
if Sbd<=0 then
return false
end
local acd=Tbd/Pbd
local bcd=acd>0 and Sbd/acd or math.huge
local ccd={baseTime=Rbd,loss=Qbd,atEnd=Sbd,rate=acd,killTime=bcd}
return Rbd<bb.BASE_SOON and bcd>Rbd*bb.BASE_MARGIN,ccd
end
