if Icd and Jcd and not V.isFarm(Icd.Value)and not V.allyBuff(Icd.Value)then
local Kcd,Lcd=U.flat(Gcd:GetPivot().Position),Jcd.Value
if(not Ccd.fly or bb.canAir(Gcd))and(Kcd-Ecd).Magnitude>Lcd then
for Mcd,Ncd in ipairs(bb.samples or{})do
if Ncd.prog>Ccd.prog and(U.flat(Ncd.pos)-Kcd).Magnitude<=Lcd then
Dcd=Dcd+1
break
end
end
end
end
end
return Dcd
