end
local Qcd=workspace:FindFirstChild(Mje[4505])and workspace._BASES:FindFirstChild(Mje[4044])
local Rcd=Qcd and Qcd:FindFirstChild(Mje[4254])and Qcd.base:FindFirstChild(Mje[4255])
local Scd=Rcd and Rcd:FindFirstChildOfClass(Mje[2390])
if not Scd or Scd.Health<=0 then
return
end
local Tcd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local Ucd=U.now()
bb.leakTrack=bb.leakTrack or{}
local Vcd=bb.leakTrack
local Wcd,Xcd={},nil
for Ycd,Zcd in ipairs(bb.enemies or{})do
if Zcd.m then
Wcd[Zcd.m]=true
local _cd,bdd=tonumber(Zcd.hp)or 0,tonumber(Zcd.prog)or 0
local cdd=Vcd[Zcd.m]
if not cdd then
Vcd[Zcd.m]={t=Ucd,hp=_cd,prog=bdd}
else
if Ucd-cdd.t>=bb.LEAK_WIN then
cdd.pace,cdd.net=(bdd-cdd.prog)/(Ucd-cdd.t),(cdd.hp-_cd)/(Ucd-cdd.t)
cdd.t,cdd.hp,cdd.prog=Ucd,_cd,bdd
end
if cdd.pace and cdd.pace>0 and _cd>0 then
local ddd=(1-bdd)/cdd.pace
local edd=math.max(0,cdd.net or 0)
local fdd=_cd-edd*ddd
if fdd>0 and ddd<=bb.LEAK_SOON and ddd>=bb.LEAK_MIN then
local gdd=Zcd.m:FindFirstChildOfClass(Mje[2390])
local hdd=Scd.Health/math.max(1,Tcd*(gdd and gdd.MaxHealth or _cd))
local idd=edd>0 and fdd/edd or math.huge
if idd>hdd*bb.LEAK_MARGIN and(ddd<=bb.LEAK_AHEAD or bb.leakAhead(Zcd)==0)and(not Xcd or ddd<Xcd.left)then
Xcd={left=ddd,arriving=fdd,net=edd,baseTime=hdd,hp=_cd}
end
end
end
end
end
end
for jdd in pairs(Vcd)do
if not Wcd[jdd]then
Vcd[jdd]=nil
end
end
if Ocd then
return Xcd~=nil,Xcd
end
if not Xcd then
return
end
bb.bailNote(Pcd,Mje[4499])
F.log(1,Mje[2663],string.format(Mje[4508],bb.wave(),tonumber(bb.total)or 0,math.floor(Xcd.left+0.5),U.fmt(Xcd.hp),U.fmt(Xcd.arriving),U.fmt(Xcd.net),Xcd.baseTime))
pcall(F.saveNow)
F.request(Mje[2066],Mje[4092])
