function bb.allPast(kdd)
local ldd={}
for mdd,ndd in ipairs(bb.mine or{})do
local odd=ndd._stats
local pdd=odd.id.Value
if not V.isFarm(pdd)and not V.allyBuff(pdd)and odd:FindFirstChild(Mje[2247])then
local qdd=tonumber(odd.range.Value)or 0
local rdd=bb.coverMax[ndd]
if not(rdd and rdd.r==qdd)then
local sdd,tdd=U.flat(ndd:GetPivot().Position),-1
for udd,vdd in ipairs(bb.samples or{})do
if vdd.prog>tdd and(U.flat(vdd.pos)-sdd).Magnitude<=qdd then
tdd=vdd.prog
end
end
rdd={r=qdd,far=tdd}
bb.coverMax[ndd]=rdd
end
table.insert(ldd,{far=rdd.far,air=bb.canAir(ndd)})
end
end
if#ldd==0 then
return false
end
for wdd,xdd in ipairs(kdd)do
for ydd,zdd in ipairs(ldd)do
if(not xdd.fly or zdd.air)and zdd.far>=(tonumber(xdd.prog)or 0)then
return false
end
end
end
return true
end
function bb.fbTick()
