Ddd=Fdd
break
end
end
local Hdd=bb.fb
if not Ddd then
if Hdd and not Hdd.gone then
Hdd.gone=U.now()
end
return
end
local Idd=Ddd.m:FindFirstChildOfClass(Mje[2390])
local Jdd=(Idd and Idd.MaxHealth>0)and Idd.MaxHealth or Ddd.hp
local Kdd=(N.Units[Cdd]and N.Units[Cdd].name)or Cdd
if not Hdd or Hdd.m~=Ddd.m then
Hdd={m=Ddd.m,id=Cdd,name=Kdd,wave=bb.wave(),t0=U.now(),max=Jdd,low=1,assassin=Add.assassin,beatAt=tonumber(Add.beatAt)or 0.5,walk=Add.walk}
bb.fb=Hdd
