Hdd.low=math.min(Hdd.low,Hdd.share)
local Ldd,Mdd=pcall(N.PATH.get_unit_path_progress,Ddd.m)
Hdd.gp=Ldd and tonumber(Mdd)or nil
if Hdd.assassin and not Hdd.beaten and Hdd.share<=Hdd.beatAt+0.005 then
Hdd.beaten=U.now()
F.log(1,Mje[2663],string.format(Mje[4510],Kdd,math.floor(Hdd.share*100+0.5)))
end
if#(bb.enemies or{})==1 and bb.total and bb.wave()>=bb.total then
Hdd.aloneT=Hdd.aloneT or U.now()
Hdd.alone=math.max(Hdd.alone or 0,U.now()-Hdd.aloneT)
else
Hdd.aloneT=nil
end
end
