local Vid,Wid,Xid=0,0,nil
for Yid,Zid in ipairs(Hid)do
if Zid~=Sid and(U.flat(Zid.m:GetPivot().Position)-Tid).Magnitude<=Uid then
Vid,Wid=Vid+Zid.dps,Wid+1
if not Xid or Zid.dps>Xid.dps then
