end
local bjd,cjd=bb.wave(),(bb.total or 30)-bb.wave()
local djd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local ejd=Fid.fresh
local fjd=not djd and cjd>3
Fid.waits=ejd and ejd.lvl<=Fid.top.lvl and Fid.top.lvl<Fid.top.max and fjd or false
local gjd=(not ejd or ejd.lvl>=Fid.top.lvl)and Fid.coming and fjd
local hjd=bb.cloneCard and Fid.top.lvl>=Fid.top.max and fjd
local ijd=ejd and ejd.lvl>Fid.top.lvl and Fid.near<0.3*ejd.dps
Fid.ready=gid and ejd~=nil and not ijd and(not(Fid.waits or gjd or hjd)or bjd-(bb.mergeHeldAt or bjd)>=5)
bb.holdNoCardAt=(Fid.waits and not gid)and(bb.holdNoCardAt or bjd)or nil
Fid.hold=Fid.waits and(gid or bjd-(bb.holdNoCardAt or bjd)<4)
bb.mergePlan=Fid
F.status(Mje[4449],ejd and string.format(Mje[4537],V.name(Fid.id),Fid.n,Fid.n==1 and Mje[4538]or Mje[4539],ejd.lvl,Fid.ready and Mje[4540]or(gid and Mje[4541]or Mje[4542]))or string.format(Mje[4543],V.name(Fid.id)))
end
